UPDATE shopping_cart.discount_rules 
SET rule_name = #{ruleName}, rule_type = #{ruleType}, category = #{category}, 
    min_quantity = #{minQuantity}, min_cart_value = #{minCartValue}, loyalty_level = #{loyaltyLevel},
    discount_percentage = #{discountPercentage}, is_active = #{isActive}
WHERE id = #{id}
